mapper.select:
/* CastChknMapper.retrieveChknQueueRawList */ SELECT A.SMLT_ACTL_DT, B.PSG_FCLT_CD, SUBSTR(B.PSG_FCLT_CD, -3, 1) AS ISLAND, NVL(A.WTNG_PSG_CNT, 0) AS WTNG_PSG_CNT, NVL(A.TRNST_PSG_CNT, 0) AS TRNST_PSG_CNT, NVL(A.AVG_WTNG_HR, 0) AS WTNG_HR, NVL(A.AVG_PRCS_HR, 0) AS PRCS_HR FROM PMOWN.TN_PM_SMLT_RSLT_DTL A INNER JOIN PMOWN.TN_PM_SMLT_PSG_FCLT B ON A.PSG_FCLT_CD = B.PSG_FCLT_CD WHERE 1 = 1 AND A.SMLT_ID = #{smltId} AND B.TMNL_ID = #{tmnlId} AND B.USE_YN = 'Y' AND B.UP_PSG_FCLT_CD = #{upPsgFcltCd}
AND A.SMLT_MDL_SN = #{smltMdlSn}
ORDER BY A.SMLT_ACTL_DT, B.PSG_FCLT_CD

/* CastChknMapper.retrieveChknBoothOperList */ SELECT SUBSTR(X.CKNCT_ID, 1, 1) AS ISLAND, X.CKNCT_ID, X.BGN_DT, X.END_DT FROM (
SELECT A.CKNCT_ID, A.ALOT_BGN_DT AS BGN_DT, A.ALOT_END_DT AS END_DT FROM () A INNER JOIN CAOWN.TN_CA_CKNCT CIC ON A.CKNCT_ID = CIC.CKNCT_ID AND A.TMNL_ID = CIC.TMNL_ID WHERE CIC.USE_YN = 'Y' AND CIC.CKNCT_USE_CRG_APLCN_TYPE_CD IN ('A', 'B') AND A.TMNL_ID = #{tmnlId} AND A.CKNCT_ID NOT LIKE 'X%' AND A.CKNCT_ID NOT LIKE 'Y%' AND A.CKNCT_ID NOT LIKE 'R%' AND A.CKNCT_ID NOT LIKE 'S%' AND A.ALOT_BGN_DT < A.ALOT_END_DT
SELECT A.CKNCT_ID, TO_DATE(A.CHKN_OPEN_PRNMNT_DT, 'YYYYMMDDHH24MI') AS BGN_DT, TO_DATE(A.CHKN_CLOSE_PRNMNT_DT, 'YYYYMMDDHH24MI') AS END_DT FROM PMOWN.TN_PM_SMLT_CKNCT_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = REPLACE(#{cknctAlctnRsrcId}, 'CA', '') AND A.TMNL_ID = #{tmnlId} AND A.CHKN_OPEN_PRNMNT_DT IS NOT NULL AND A.CHKN_CLOSE_PRNMNT_DT IS NOT NULL
) X ORDER BY ISLAND, X.CKNCT_ID, X.BGN_DT

/* CastChknMapper.retrieveChknList */
SELECT Y.ISLAND, Y.COUNTER_NUM, Y.ALN_CD, Y.START_HOUR AS "START",
CASE WHEN Y.END_HOUR <= Y.START_HOUR THEN 24 ELSE Y.END_HOUR END AS "END" FROM ( SELECT Z.ISLAND, Z.COUNTER_NUM, Z.ALN_CD, TO_NUMBER(SUBSTR(Z.STA_HM, 1, 2)) AS START_HOUR, CEIL(TO_NUMBER(Z.END_HM) / 100) AS END_HOUR FROM ( SELECT SUBSTR(A.CKNCT_ID, 0, 1) AS ISLAND, TO_NUMBER(SUBSTR(A.CKNCT_ID, 2, 2)) AS COUNTER_NUM, A.ALN_CD, CASE WHEN A.EST_BGNG_HM IS NOT NULL AND A.EST_END_HM IS NOT NULL THEN A.EST_BGNG_HM ELSE A.LAST_BGNG_HM END AS STA_HM, CASE WHEN A.EST_BGNG_HM IS NOT NULL AND A.EST_END_HM IS NOT NULL THEN A.EST_END_HM ELSE A.LAST_END_HM END AS END_HM FROM () A WHERE 1 = 1 AND A.OPER_YMD = #{ymd} AND A.TMNL_ID = #{tmnlId} AND REGEXP_LIKE(SUBSTR(A.CKNCT_ID, 2, 2), '^[0-9]+$') ) Z WHERE Z.STA_HM IS NOT NULL AND Z.END_HM IS NOT NULL AND Z.STA_HM != Z.END_HM ) Y ORDER BY Y.ISLAND, Y.COUNTER_NUM, Y.ALN_CD

/* CastChknMapper.retrieveAlnCdList */

SELECT DISTINCT A.ALN_CD
FROM () A
WHERE 1 = 1
AND A.OPER_YMD = #{ymd}
AND A.TMNL_ID = #{tmnlId}
ORDER BY A.ALN_CD

/* CastChknMapper.retrieveUserChknIslandList */
SELECT
    A.CHKN_ISL_CD AS ISLAND,
    NVL(A.BOOTH_CNT, 0) AS BOOTH_CNT,
    NVL(A.KOS_CNT, 0) AS KIOSK_CNT,
    NVL(A.SBD_CNT, 0) AS BAG_DROP_CNT
FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.CHKN_ISL_CD

/* CastChknMapper.retrieveUserChknBoothAltmntList */
SELECT
    A.CHKN_ISL_CD AS ISLAND,
    A.BOOTH_NO,
    A.ALN_CD,
    A.OPER_BGNG_HOUR,
    A.OPER_END_HOUR
FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_ALTMNT A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.CHKN_ISL_CD, A.BOOTH_NO, A.ALTMNT_SN

mapper.delete:
/* CastChknMapper.deleteUserChknIslandList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

/* CastChknMapper.deleteUserChknBoothAltmntList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_ALTMNT
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

mapper.insert:
/* CastChknMapper.insertUserChknIslandList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_ISL ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, CHKN_ISL_CD, BOOTH_CNT, KOS_CNT, SBD_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{island.island}, #{island.boothCnt}, #{island.kioskCnt}, #{island.bagDropCnt}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastChknMapper.insertUserChknBoothAltmntList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_ALTMNT ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, CHKN_ISL_CD, BOOTH_NO, ALTMNT_SN, ALN_CD, OPER_BGNG_HOUR, OPER_END_HOUR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{island.island}, #{booth.boothNo}, #{altmntIdx} + 1, #{altmnt.alnCd}, #{altmnt.operBgngHour}, #{altmnt.operEndHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL
